def shade(cell, color):
    tcPr=cell._tc.get_or_add_tcPr(); s=OxmlElement('w:shd'); s.set(qn('w:fill'),color); tcPr.append(s)
def cell_margin(c):
    tcPr=c._tc.get_or_add_tcPr(); m=OxmlElement('w:tcMar')
    for k in ('top','start','bottom','end'):
        n=OxmlElement('w:'+k); n.set(qn('w:w'),'100' if k in ('top','bottom') else '120'); n.set(qn('w:type'),'dxa'); m.append(n)
    tcPr.append(m)
def width(c, dxa):
    tcPr=c._tc.get_or_add_tcPr(); w=OxmlElement('w:tcW'); w.set(qn('w:w'),str(dxa)); w.set(qn('w:type'),'dxa'); tcPr.append(w)
def table(doc, heads, rows, widths=None):
    if widths is None: widths=[9360//len(heads)]*len(heads)
    t=doc.add_table(rows=1, cols=len(heads)); t.style='Table Grid'; t.alignment=WD_TABLE_ALIGNMENT.LEFT; t.autofit=False
    for i,h in enumerate(heads):
        c=t.rows[0].cells[i]; c.text=h; shade(c,LIGHT); width(c,widths[i]); cell_margin(c)
        for r in c.paragraphs[0].runs: r.bold=True; r.font.size=Pt(8.5)
    for row in rows:
        cs=t.add_row().cells
        for i,v in enumerate(row):
            cs[i].text=str(v); width(cs[i],widths[i]); cell_margin(cs[i]); cs[i].vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
            for p in cs[i].paragraphs:
                for r in p.runs:r.font.size=Pt(8.2)
    doc.add_paragraph(); return t
def para(doc, txt='', bold=False, color=None, size=None, italic=False):
    p=doc.add_paragraph(); r=p.add_run(txt); r.bold=bold; r.italic=italic
    if color:r.font.color.rgb=RGBColor.from_string(color)
    if size:r.font.size=Pt(size)
    return p
def h(doc,txt,l=1):doc.add_heading(txt,l)
def bullets(doc,xs):
    for x in xs: doc.add_paragraph(x,style='List Bullet')
def page(doc): doc.add_page_break()
def note(doc, txt):
    t=doc.add_table(rows=1,cols=1); t.style='Table Grid'; c=t.cell(0,0); c.text='CÓMO DILIGENCIAR: '+txt; shade(c,WARN); cell_margin(c)
    for r in c.paragraphs[0].runs:r.bold=True;r.font.size=Pt(9)
    doc.add_paragraph()
def setup(doc):
    s=doc.sections[0]; s.top_margin=Inches(.75);s.bottom_margin=Inches(.75);s.left_margin=Inches(.8);s.right_margin=Inches(.8)
    st=doc.styles['Normal'];st.font.name='Calibri';st._element.rPr.rFonts.set(qn('w:ascii'),'Calibri');st._element.rPr.rFonts.set(qn('w:hAnsi'),'Calibri');st.font.size=Pt(10);st.paragraph_format.space_after=Pt(5);st.paragraph_format.line_spacing=1.1
    for name,size,color in [('Title',23,DARK),('Heading 1',15,BLUE),('Heading 2',12,BLUE),('Heading 3',11,DARK)]:
        x=doc.styles[name];x.font.name='Calibri';x.font.size=Pt(size);x.font.color.rgb=RGBColor.from_string(color);x.font.bold=True
    hp=s.header.paragraphs[0];hp.alignment=WD_ALIGN_PARAGRAPH.RIGHT; rr=hp.add_run('Guía de diligenciamiento | EL VITRAL');rr.font.size=Pt(8);rr.font.color.rgb=RGBColor(100,100,100)
    fp=s.footer.paragraphs[0];fp.alignment=WD_ALIGN_PARAGRAPH.CENTER;rr=fp.add_run('Usa esta guía junto al formato institucional original.');rr.font.size=Pt(8);rr.font.color.rgb=RGBColor(100,100,100)

